import asyncio
import json
import math
import os

import mcp.types as types
from eth_account import Account
from polymarket_mcp import server as upstream
from polymarket_mcp.config import PolymarketConfig

# A session or health probe ending must never cancel a member's open orders.
os.environ['CANCEL_ON_SHUTDOWN'] = 'false'
API_FIELDS = ('POLYMARKET_API_KEY', 'POLYMARKET_API_SECRET', 'POLYMARKET_PASSPHRASE')
ORDER_READS = {'suggest_order_price', 'get_order_status', 'get_open_orders', 'get_order_history'}
PUBLIC_REALTIME = {'subscribe_market_prices', 'subscribe_orderbook_updates',
                   'subscribe_market_resolution', 'get_realtime_status', 'unsubscribe_realtime'}


def enabled(name):
    value = os.environ.get(name, 'false').lower()
    if value not in {'true', 'false'}:
        raise ValueError(name + ' must be true or false')
    return value == 'true'


def load_config():
    key = os.environ.get('POLYGON_PRIVATE_KEY', '').strip()
    address = os.environ.get('POLYGON_ADDRESS', '').strip()
    api = {name: os.environ.get(name) or None for name in API_FIELDS}
    if (address or any(api.values())) and not key:
        raise ValueError('A private key is required with wallet address or API credentials')
    if any(api.values()) and not all(api.values()):
        raise ValueError('Provide all three API credentials or leave all three empty')
    if key:
        try:
            derived = Account.from_key(key).address
        except Exception:
            raise ValueError('Invalid Polygon private key') from None
        if address and address.lower() != derived.lower():
            raise ValueError('Wallet address must match the private key (EOA wallets only)')
        address = derived
    try:
        config = PolymarketConfig(
            _env_file=None, DEMO_MODE=not bool(key),
            POLYGON_PRIVATE_KEY=key, POLYGON_ADDRESS=address,
            POLYMARKET_API_KEY_NAME='localish' if all(api.values()) else None,
            ENABLE_AUTONOMOUS_TRADING=enabled('ENABLE_TRADING') and enabled('ENABLE_AUTONOMOUS_TRADING'),
            **api)
    except Exception:
        # Pydantic errors can include raw credential inputs. Never log them.
        raise ValueError('Invalid Polymarket settings; check wallet and service settings') from None
    for name in ('MAX_ORDER_SIZE_USD', 'MAX_TOTAL_EXPOSURE_USD', 'MAX_POSITION_SIZE_PER_MARKET',
                 'MIN_LIQUIDITY_REQUIRED', 'REQUIRE_CONFIRMATION_ABOVE_USD'):
        value = getattr(config, name)
        if not math.isfinite(value) or value < 0:
            raise ValueError(name + ' must be finite and non-negative')
    return config


async def wallet_credentials(self, *args, **kwargs):
    if not upstream.config or upstream.config.DEMO_MODE:
        raise RuntimeError('No member wallet configured; public research remains available')
    try:
        # Reuse nonce-zero credentials across Localish sessions before creating any.
        try:
            credentials = await asyncio.to_thread(self.get_client().derive_api_key)
        except Exception:
            credentials = await asyncio.to_thread(self.get_client().create_api_key)
        self.api_creds = credentials
        self._initialize_client()
        for name, value in zip(API_FIELDS, (credentials.api_key, credentials.api_secret, credentials.api_passphrase)):
            setattr(upstream.config, name, value)
        upstream.config.POLYMARKET_API_KEY_NAME = 'localish'
        return credentials
    except Exception:
        raise RuntimeError('Wallet authentication failed; check wallet or API credentials') from None


def authenticated():
    return bool(upstream.config and not upstream.config.DEMO_MODE and
                upstream.polymarket_client and upstream.polymarket_client.has_api_credentials())


upstream.server.name = 'polymarket-localish'
upstream.load_config = load_config
upstream.PolymarketClient.create_api_credentials = wallet_credentials
original_call_tool = upstream.call_tool


@upstream.server.list_tools()
async def list_tools():
    tools = upstream.market_discovery.get_tools()
    # This upstream holder endpoint is a placeholder, including with a wallet.
    tools += [tool for tool in upstream.market_analysis.get_tools() if tool.name != 'get_market_holders']
    tools += [tool for tool in upstream.realtime.get_tools()
              if tool.name in PUBLIC_REALTIME or authenticated()]
    if authenticated():
        tools += upstream.portfolio_integration.get_portfolio_tool_definitions()
        tools += [tool for tool in upstream.get_tool_definitions()
                  if tool.name in ORDER_READS or enabled('ENABLE_TRADING')]
    tools.append(types.Tool(name='check_connection', description='Check public API and configured wallet access without placing orders.',
                            inputSchema={'type': 'object', 'properties': {}, 'additionalProperties': False}))
    return tools


def error(message):
    return types.CallToolResult(isError=True, content=[types.TextContent(type='text', text=message)])


@upstream.server.call_tool()
async def call_tool(name, arguments):
    # Recheck the same boundary on direct calls; tool visibility is not authorization.
    if name not in {tool.name for tool in await list_tools()}:
        return error('Tool unavailable. Trading requires a member wallet and ENABLE_TRADING=true.')
    if name == 'check_connection':
        if upstream.config and not upstream.config.DEMO_MODE:
            if not authenticated():
                return error('Configured wallet could not authenticate')
            wallet = await call_tool('get_open_orders', {})
            if wallet.isError:
                return error('Configured wallet failed its authenticated connection check')
        return await call_tool('get_trending_markets', {'timeframe': '24h', 'limit': 1})
    content = await original_call_tool(name, arguments)
    failed = False
    for item in content:
        if item.type != 'text':
            continue
        try:
            payload = json.loads(item.text)
        except (ValueError, TypeError):
            failed |= item.text.startswith('Error:')
        else:
            failed |= isinstance(payload, dict) and ('error' in payload or payload.get('success') is False)
    return types.CallToolResult(content=content, isError=failed)


if __name__ == '__main__':
    upstream.run()
